/**
 * ULID (https://github.com/ulid/spec): 48-bit time + 80-bit randomness, Crockford base32.
 * Monotonic: within the same millisecond (or if the clock goes backwards) the random part is
 * incremented, so ids generated by one device always sort in creation order.
 */
import type { Aleatorio, Reloj } from './puertos.ts';

const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
const TIME_LEN = 10;
const RANDOM_LEN = 16;
const MAX_TIME = 2 ** 48 - 1;

function encodeTime(ms: number): string {
  if (!Number.isInteger(ms) || ms < 0 || ms > MAX_TIME) throw new RangeError(`ULID time out of range: ${ms}`);
  let out = '';
  let t = ms;
  for (let i = 0; i < TIME_LEN; i++) {
    out = ALPHABET[t % 32] + out;
    t = Math.floor(t / 32);
  }
  return out;
}

/** 80 random bits as 16 base32 digits (5 bits each). */
function randomDigits(random: Aleatorio): number[] {
  const bytes = random.bytes(RANDOM_LEN);
  return Array.from(bytes, (b) => b & 31);
}

function increment(digits: number[]): number[] {
  const next = [...digits];
  for (let i = next.length - 1; i >= 0; i--) {
    if (next[i] < 31) {
      next[i]++;
      return next;
    }
    next[i] = 0;
  }
  throw new RangeError('ULID random part overflow');
}

/** Returns a monotonic ULID generator bound to a clock and a random source. */
export function createUlidFactory(clock: Reloj, random: Aleatorio): () => string {
  let lastTime = -1;
  let lastDigits: number[] = [];
  return () => {
    const now = clock.ahora();
    encodeTime(now); // validates range
    if (now > lastTime) {
      lastTime = now;
      lastDigits = randomDigits(random);
    } else {
      lastDigits = increment(lastDigits);
    }
    return encodeTime(lastTime) + lastDigits.map((d) => ALPHABET[d]).join('');
  };
}

/** Milliseconds encoded in a ULID. */
export function ulidTime(id: string): number {
  let t = 0;
  for (const ch of id.slice(0, TIME_LEN)) {
    const v = ALPHABET.indexOf(ch);
    if (v < 0) throw new Error(`invalid ULID: ${id}`);
    t = t * 32 + v;
  }
  return t;
}
